#!/bin/bash
# Task 132-w3-perf-ab -- meshsim sim/ WORKER3 (branch sim-w3). TIMING TASK: keep the box quiet while it runs.
# The performance pass, before and after, in one task (D13: pinned; D18: clang release; D21: nothing machine-specific):
#   before = 0c7df79 (increment 5 merged, the Hold note), after = 057a9d5 (the performance pass, D24, 32-bit ring fields).
#   1. the machine recorded (CPU model, core types and CPUs, clocks, caches, memory, compilers): W5's machine.inc;
#      the CPU pinned is the first P core's first thread, detected, or PIN=n; P and E CPU lists may be given as $1 $2;
#   2. both trees built (clang release); each build's own checks; the 67 goldens on the after build's engine under the six
#      option sets;
#   3. W5's bench_controller (10^7 iterations of a 13-cycle loop), before and after interleaved, REPS (5) each, and the
#      plain core alone; W4's framework mesh (one chip, 200000 cycles), interleaved, REPS each; footprint per chip from
#      Sizes; the mesh digests equal;
#   4. perf stat and perf record (top symbols) of each; TABLE.txt.
# From an embedded kit (both trees: sim's Makefile, src, tests, fw, bench/threads, the boot ROM, the riscv-tests images).
# Expected ~10 min. Writes only results/132-w3-perf-ab/. Scratch in /tmp, removed first and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/132-w3-perf-ab; mkdir -p "$RES"
W=/tmp/w3-132-w3-perf-ab; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "7d8302d55d095465b4a57330859340124813ac3fafc18d7b8f444023889b459e" ] || { echo "kit sha256 mismatch (want 7d8302d55d095465b4a57330859340124813ac3fafc18d7b8f444023889b459e)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
echo 0c7df79 > "$W/before.rev"; echo 057a9d5 > "$W/after.rev"
FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
# machine.inc (WORKER5's Quest tasks; D21: nothing machine-specific baked in; to be replaced by W4's sim/tools/machine.sh).
# Sourced by a task. Defines:
#   machine_record FILE   writes what the machine is: CPU model, sockets, cores and threads, core types (P/E) with their
#                         CPUs and max/min clocks, caches, memory, kernel, compilers and Java; and prints it
#   expand LIST           "0-3,8" -> "0,1,2,3,8"
# and sets, from the arguments "$1" (P CPUs) and "$2" (E CPUs) when given, else detected:
#   P_CPUS    the performance cores' CPUs (hybrid: /sys/devices/cpu_core/cpus; otherwise every online CPU)
#   P_ONE     one CPU per P core (the first of each thread_siblings_list)
#   E_CPUS    the efficiency cores' CPUs (/sys/devices/cpu_atom/cpus), or empty
#   ALL_CPUS  every online CPU
expand() { local out= p a b; IFS=, read -ra parts <<< "$1"; for p in "${parts[@]}"; do
  if [[ $p == *-* ]]; then a=${p%-*}; b=${p#*-}; for ((i=a; i<=b; i++)); do out+=${out:+,}$i; done; elif [ -n "$p" ]; then out+=${out:+,}$p; fi; done; echo "$out"; }
ALL_CPUS=$(expand "$(cat /sys/devices/system/cpu/online)")
if [ -n "${1:-}" ]; then P_CPUS=$(expand "$1"); elif [ -r /sys/devices/cpu_core/cpus ]; then P_CPUS=$(expand "$(cat /sys/devices/cpu_core/cpus)"); else P_CPUS=$ALL_CPUS; fi
if [ -n "${2:-}" ]; then E_CPUS=$(expand "$2"); elif [ -r /sys/devices/cpu_atom/cpus ]; then E_CPUS=$(expand "$(cat /sys/devices/cpu_atom/cpus)"); else E_CPUS=; fi
P_ONE=; for c in ${P_CPUS//,/ }; do f=$(cut -d, -f1 /sys/devices/system/cpu/cpu$c/topology/thread_siblings_list | cut -d- -f1); [ "$f" = "$c" ] && P_ONE+=${P_ONE:+,}$c; done
count() { [ -z "$1" ] && echo 0 || echo "$1" | tr ',' '\n' | wc -l; }
khz() { cat /sys/devices/system/cpu/cpu$1/cpufreq/cpuinfo_$2_freq 2>/dev/null || echo "?"; }
machine_record() {
  { echo "model:     $(lscpu | sed -n 's/^Model name: *//p' | head -1)"
    echo "sockets:   $(lscpu | sed -n 's/^Socket(s): *//p'), CPUs online $ALL_CPUS ($(count "$ALL_CPUS"))"
    local p1=${P_CPUS%%,*} e1=${E_CPUS%%,*}
    echo "P cores:   $(count "$P_ONE") cores, CPUs $P_CPUS ($(count "$P_CPUS") threads), max $(khz $p1 max) kHz, min $(khz $p1 min) kHz"
    [ -n "$E_CPUS" ] && echo "E cores:   $(count "$E_CPUS") cores, CPUs $E_CPUS, max $(khz $e1 max) kHz, min $(khz $e1 min) kHz"
    echo "governor:  $(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor 2>/dev/null || echo ?)"
    echo "caches:    $(lscpu | grep -E '^L[123]' | sed 's/  */ /g' | tr '\n' ';')"
    echo "memory:    $(grep MemTotal /proc/meminfo)"
    echo "kernel:    $(uname -sr)"
    echo "gcc:       $(g++ --version 2>/dev/null | head -1)"
    echo "clang:     $(clang++ --version 2>/dev/null | head -1)"
    echo "java:      $(java -version 2>&1 | head -1)"
  } > "$1"
  cat "$1"
}
# ---- the body (W3's performance pass, A/B): sourced after the kit is unpacked into $W ----
EV=cycles,instructions,cache-misses,L1-dcache-load-misses,branch-misses
REPS=${REPS:-5}
sec "the machine (D21)"
machine_record "$RES/machine.txt"
PIN=${PIN:-${P_ONE%%,*}}
echo "pinned to CPU $PIN (the first P core's first thread unless PIN is given); P CPUs $P_CPUS; E CPUs ${E_CPUS:-none}" | tee -a "$RES/machine.txt"
perf stat -e instructions true > /dev/null 2>&1 && PERF=1 || PERF=0
echo "perf: $([ $PERF = 1 ] && echo available || echo not available)" | tee -a "$RES/machine.txt"

for v in before after; do
  sec "build $v ($(cat $W/$v.rev)): clang release"
  ( cd "$W/$v/sim" && make -j"$(nproc)" CC_NAME=clang MODE=release build/clang-release/bench_controller build/clang-release/bench_threads build/clang-release/golden > "$W/build-$v.log" 2>&1 )
  if [ $? -eq 0 ]; then verdict "build $v" PASS; else tail -20 "$W/build-$v.log"; verdict "build $v" FAIL; fi
done
BC() { ( cd "$W/$1/sim" && taskset -c "$PIN" ./build/clang-release/bench_controller "${@:2}" ); }
MESH() { ( cd "$W/$1/sim" && taskset -c "$PIN" ./build/clang-release/bench_threads --form 1 --chip mesh --chips 1 --threads 1 --cpus "$PIN" "${@:2}" ); }

sec "sanity: each build's own checks"
for v in before after; do
  out=$(BC $v --iters 1000 --reps 1 --only engine 2>&1 | head -1); echo "$v: $out"
  echo "$out" | grep -q "engine = direct driver" && verdict "controller check $v" PASS || verdict "controller check $v" FAIL
done
sec "the goldens on the after build (67 x the six option sets: ready-driven, shuffle seeds 1-3, instance-major, step-all)"
( cd "$W/after/sim" && taskset -c "$PIN" ./build/clang-release/golden --engine > "$RES/golden-engine-after.txt" 2>&1 ); rc=$?
tail -3 "$RES/golden-engine-after.txt"; [ $rc -eq 0 ] && verdict "goldens after (engine, six option sets)" PASS || verdict "goldens after (engine, six option sets)" FAIL

sec "the controller: bench_controller, 10^7 iterations of the 13-cycle loop, before and after interleaved, $REPS each"
for r in $(seq 1 $REPS); do for v in before after; do
  BC $v --reps 1 --only engine 2>&1 | grep '^engine' | sed "s/^/$v rep $r: /" | tee -a "$RES/controller.txt"
done; done
for v in before after; do BC $v --reps 1 --only core 2>&1 | grep '^core' | sed "s/^/$v: /" | tee -a "$RES/controller.txt"; done

sec "the mesh (W4's framework mesh, one chip, 200000 cycles), before and after interleaved, $REPS each"
for r in $(seq 1 $REPS); do for v in before after; do
  MESH $v --cycles 200000 2>&1 | grep '^threads' | sed "s/^/$v rep $r: /" | tee -a "$RES/mesh.txt"
done; done
for v in before after; do
  ( cd "$W/$v/sim" && ./build/clang-release/bench_threads --sizes --chip mesh ) > "$RES/sizes-$v.txt" 2>&1
  head -1 "$RES/sizes-$v.txt" | sed "s/^/$v: /"
done
d1=$(grep '^before' "$RES/mesh.txt" | grep -o 'digest=[0-9a-f]*' | sort -u); d2=$(grep '^after' "$RES/mesh.txt" | grep -o 'digest=[0-9a-f]*' | sort -u)
echo "mesh digests: before $d1, after $d2"
[ -n "$d1" ] && [ "$d1" = "$d2" ] && [ "$(echo "$d1" | wc -l)" = 1 ] && verdict "mesh digest unchanged" PASS || verdict "mesh digest unchanged" FAIL

if [ $PERF = 1 ]; then
  sec "perf stat (one run each)"
  for v in before after; do
    ( cd "$W/$v/sim" && taskset -c "$PIN" perf stat -x, -e $EV -o "$RES/stat-controller-$v.csv" -- ./build/clang-release/bench_controller --reps 1 --only engine > /dev/null 2>&1 )
    ( cd "$W/$v/sim" && taskset -c "$PIN" perf stat -x, -e $EV -o "$RES/stat-mesh-$v.csv" -- ./build/clang-release/bench_threads --form 1 --chip mesh --chips 1 --threads 1 --cpus "$PIN" --cycles 200000 > /dev/null 2>&1 )
    for b in controller mesh; do echo "-- $b $v"; grep -v '^#' "$RES/stat-$b-$v.csv" | grep -v '^$' | cut -d, -f1,3; done
  done
  sec "perf record: the top symbols (self), for the engine's share"
  for v in before after; do for b in controller mesh; do
    if [ $b = controller ]; then cmd=(./build/clang-release/bench_controller --reps 1 --only engine); else cmd=(./build/clang-release/bench_threads --form 1 --chip mesh --chips 1 --threads 1 --cpus "$PIN" --cycles 200000); fi
    ( cd "$W/$v/sim" && taskset -c "$PIN" perf record -q -o "$W/perf-$b-$v.data" -- "${cmd[@]}" > /dev/null 2>&1 \
      && perf report -q -i "$W/perf-$b-$v.data" --stdio --sort symbol --no-children 2>/dev/null | grep -v '^#' | grep -v '^$' | head -30 ) > "$RES/perf-$b-$v.txt"
    echo "-- $b $v: the top 12"; head -12 "$RES/perf-$b-$v.txt"
  done; done
fi

sec "the table"
python3 - "$RES" <<'PY'
import re, statistics, sys, os
R = sys.argv[1]
def med(xs): return statistics.median(xs) if xs else float('nan')
ctl = open(os.path.join(R, 'controller.txt')).read().splitlines()
mesh = open(os.path.join(R, 'mesh.txt')).read().splitlines()
def ns(v): return [float(m.group(1)) for l in ctl if l.startswith(v + ' rep') for m in [re.search(r'([0-9.]+) ns per step', l)] if m]
def core(v): return [float(m.group(1)) for l in ctl if l.startswith(v + ': core') for m in [re.search(r'([0-9.]+) ns per step', l)] if m]
def us(v): return [float(m.group(1)) for l in mesh if l.startswith(v + ' rep') for m in [re.search(r'us_per_chip_cycle=([0-9.]+)', l)] if m]
def size(v):
    for l in open(os.path.join(R, 'sizes-%s.txt' % v)):
        m = re.search(r'total_bytes=([0-9]+)', l)
        if m: return int(m.group(1))
def perf_share(b, v):
    p = os.path.join(R, 'perf-%s-%s.txt' % (b, v))
    if not os.path.exists(p): return None
    tot = 0.0
    for l in open(p):
        m = re.match(r'\s*([0-9.]+)%\s+\S+\s+(.*)', l)
        if m and re.search(r'sim::(Engine|detail)', m.group(2)): tot += float(m.group(1))
    return tot
rows = []
b, a = med(ns('before')), med(ns('after'))
cb, ca = med(core('before')), med(core('after'))
rows.append(('controller: ns per unit step (median of %d)' % len(ns('after')), '%.2f' % b, '%.2f' % a, '%+.1f%%' % (100 * (a - b) / b)))
rows.append(('controller: the core alone, ns per step', '%.2f' % cb, '%.2f' % ca, ''))
rows.append(("controller: the engine's part, ns per step (step - core)", '%.2f' % (b - cb), '%.2f' % (a - ca), '%+.1f%%' % (100 * ((a - ca) - (b - cb)) / (b - cb))))
for bn in ('controller', 'mesh'):
    pb, pa = perf_share(bn, 'before'), perf_share(bn, 'after')
    if pb is not None: rows.append(("%s: sim::Engine/detail symbols' share (perf, self)" % bn, '%.1f%%' % pb, '%.1f%%' % pa, ''))
mb, ma = med(us('before')), med(us('after'))
rows.append(('mesh: us per mesh-cycle (median of %d)' % len(us('after')), '%.3f' % mb, '%.3f' % ma, '%+.1f%%' % (100 * (ma - mb) / mb)))
sb, sa = size('before'), size('after')
rows.append(('mesh: footprint per chip, bytes (Sizes)', str(sb), str(sa), '%+.1f%%' % (100 * (sa - sb) / sb)))
w = max(len(r[0]) for r in rows)
out = ['%-*s  %12s  %12s  %8s' % (w, '', 'before', 'after', 'change')] + ['%-*s  %12s  %12s  %8s' % ((w,) + r) for r in rows]
print('\n'.join(out))
open(os.path.join(R, 'TABLE.txt'), 'w').write('\n'.join(out) + '\n')
PY
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
